        quiz: [{ q: 'Pour corriger un bug dans un projet de 40 fichiers, le plus adapté est…', a: ['Un chat sans accès aux fichiers', 'Un agent comme Claude Code', 'Un générateur d’images'], ok: 1, why: 'L’agent lit tout le projet, lance les commandes et vérifie le résultat.' }],
        todo: ['Génère la même page d’accueil de ton fil rouge dans deux outils (ex. Claude.ai et Lovable)', 'Compare : design, textes, facilité de modification, export du code', 'Écris ton verdict en 5 lignes'],
