        key: ['Titre < 60 caractères, description < 155, image de partage 1200 × 630 en adresse complète.', 'SEO local : un seul grand titre, les mots réels des clients, fiche Google Business Profile, coordonnées identiques partout.', 'Tester l’aperçu : opengraph.xyz, LinkedIn Post Inspector, envoi WhatsApp de test.'],
        quiz: [{ q: 'Pourquoi l’image de partage doit-elle avoir une adresse complète (https://…) ?', a: ['C’est plus joli', 'Les robots de WhatsApp et LinkedIn lisent la page de l’extérieur', 'Pour Google seulement'], ok: 1, why: 'Ils ne devinent pas les chemins relatifs.' }],
        todo: ['Demande à ton agent le titre, la description et l’aperçu de partage de ton fil rouge', 'Crée l’image de partage 1200 × 630 (Canva ou Figma)', 'Vérifie l’aperçu sur opengraph.xyz'],
        res: [{ title: 'Mes balises SEO', text: 'Pour la page [nom] de [commerce, ville] : propose 3 titres (< 60 caractères) et 3 descriptions (< 155 caractères) qui contiennent ce que les clients tapent sur Google, puis écris toutes les balises Open Graph, la balise canonical et les données structurées JSON-LD de type LocalBusiness (adresse, horaires, téléphone à compléter).' }],
